   157	static char *
   158	parse_proxy_protocol_v1(struct lwan_request *request, char *buffer)
   159	{
   160	    static const size_t line_size = 108;
   161	    char *end, *protocol, *src_addr, *dst_addr, *src_port, *dst_port;
   162	    unsigned int size;
   163	    struct lwan_proxy *const proxy = request->proxy;
   164	
   165	    end = memchr(buffer, '\r', line_size);
   166	    if (UNLIKELY(!end || end[1] != '\n'))
   167	        return NULL;
   168	    *end = '\0';
   169	    size = (unsigned int) (end + 2 - buffer);
   170	
   171	    protocol = buffer + sizeof("PROXY ") - 1;
   172	    src_addr = strsep_char(protocol, ' ');
   173	    dst_addr = strsep_char(src_addr, ' ');
   174	    src_port = strsep_char(dst_addr, ' ');
   175	    dst_port = strsep_char(src_port, ' ');
   176	
   177	    if (UNLIKELY(!dst_port))
   178	        return NULL;
   179	
   180	    STRING_SWITCH(protocol) {
   181	    case MULTICHAR_CONSTANT('T', 'C', 'P', '4'): {
   182	        struct sockaddr_in *from = &proxy->from.ipv4;
   183	        struct sockaddr_in *to = &proxy->to.ipv4;
   184	
   185	        from->sin_family = to->sin_family = AF_INET;
   186	
   187	        if (UNLIKELY(inet_pton(AF_INET, src_addr, &from->sin_addr) <= 0))
   188	            return NULL;
   189	        if (UNLIKELY(inet_pton(AF_INET, dst_addr, &to->sin_addr) <= 0))
   190	            return NULL;
   191	        if (UNLIKELY(!parse_ascii_port(src_port, &from->sin_port)))
   192	            return NULL;
   193	        if (UNLIKELY(!parse_ascii_port(dst_port, &to->sin_port)))
   194	            return NULL;
   195	
   196	        break;
   197	    }
   198	    case MULTICHAR_CONSTANT('T', 'C', 'P', '6'): {
   199	        struct sockaddr_in6 *from = &proxy->from.ipv6;
   200	        struct sockaddr_in6 *to = &proxy->to.ipv6;
   201	
   202	        from->sin6_family = to->sin6_family = AF_INET6;
   203	
   204	        if (UNLIKELY(inet_pton(AF_INET6, src_addr, &from->sin6_addr) <= 0))
   205	            return NULL;
   206	        if (UNLIKELY(inet_pton(AF_INET6, dst_addr, &to->sin6_addr) <= 0))
   207	            return NULL;
   208	        if (UNLIKELY(!parse_ascii_port(src_port, &from->sin6_port)))
   209	            return NULL;
   210	        if (UNLIKELY(!parse_ascii_port(dst_port, &to->sin6_port)))
   211	            return NULL;
   212	
   213	        break;
   214	    }
   215	    default:
   216	        return NULL;
   217	    }
   218	
   219	    request->flags |= REQUEST_PROXIED;
   220	    return buffer + size;
   221	}
   222	
   223	static char *parse_proxy_protocol_v2(struct lwan_request *request, char *buffer)
   224	{
   225	    struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)buffer;
   226	    const unsigned int proto_signature_length = 16;
   227	    unsigned int size;
   228	    struct lwan_proxy *const proxy = request->proxy;
   229	
   230	    enum { LOCAL = 0x20, PROXY = 0x21, TCP4 = 0x11, TCP6 = 0x21 };
   231	
   232	    size = proto_signature_length + (unsigned int)ntohs(hdr->len);
   233	    if (UNLIKELY(size > (unsigned int)sizeof(*hdr)))
   234	        return NULL;
   235	
   236	    if (LIKELY(hdr->cmd_ver == PROXY)) {
   237	        if (hdr->fam == TCP4) {
   238	            struct sockaddr_in *from = &proxy->from.ipv4;
   239	            struct sockaddr_in *to = &proxy->to.ipv4;
   240	
   241	            to->sin_family = from->sin_family = AF_INET;
   242	
   243	            from->sin_addr.s_addr = hdr->addr.ip4.src_addr;
   244	            from->sin_port = hdr->addr.ip4.src_port;
   245	
   246	            to->sin_addr.s_addr = hdr->addr.ip4.dst_addr;
   247	            to->sin_port = hdr->addr.ip4.dst_port;
   248	        } else if (hdr->fam == TCP6) {
   249	            struct sockaddr_in6 *from = &proxy->from.ipv6;
   250	            struct sockaddr_in6 *to = &proxy->to.ipv6;
   251	
   252	            from->sin6_family = to->sin6_family = AF_INET6;
   253	
   254	            from->sin6_addr = hdr->addr.ip6.src_addr;
   255	            from->sin6_port = hdr->addr.ip6.src_port;
   256	
   257	            to->sin6_addr = hdr->addr.ip6.dst_addr;
   258	            to->sin6_port = hdr->addr.ip6.dst_port;
   259	        } else {
   260	            return NULL;
   261	        }
   262	    } else if (hdr->cmd_ver == LOCAL) {
   263	        struct sockaddr_in *from = &proxy->from.ipv4;
   264	        struct sockaddr_in *to = &proxy->to.ipv4;
   265	
   266	        from->sin_family = to->sin_family = AF_UNSPEC;
   267	    } else {
   268	        return NULL;
   269	    }
   270	
   271	    request->flags |= REQUEST_PROXIED;
   272	
   273	    buffer += size;
   274	
   275	    /* helper->crlfcrlf might be pointing to hdr; adjust */
   276	    struct lwan_request_parser_helper *helper = request->helper;
   277	    const size_t adjusted_size =
   278	        (size_t)(helper->buffer->value + helper->buffer->len - buffer);
   279	    helper->crlfcrlf = memmem(buffer, adjusted_size, "\r\n\r\n", 4);
   280	
   281	    return buffer;
   282	}
