   312	static ssize_t url_decode(char *str)
   313	{
   314	    if (UNLIKELY(!str))
   315	        return -EINVAL;
   316	
   317	    char *ch, *decoded;
   318	    for (decoded = ch = str; *ch; ch++) {
   319	        if (*ch == '%') {
   320	            char tmp =
   321	                (char)(decode_hex_digit(ch[1]) << 4 | decode_hex_digit(ch[2]));
   322	
   323	            if (UNLIKELY(!tmp))
   324	                return -EINVAL;
   325	
   326	            *decoded++ = tmp;
   327	            ch += 2;
   328	        } else if (*ch == '+') {
   329	            *decoded++ = ' ';
   330	        } else {
   331	            *decoded++ = *ch;
   332	        }
   333	    }
   334	
   335	    *decoded = '\0';
   336	    return (ssize_t)(decoded - str);
   337	}
