   443	static void parse_fragment_and_query(struct lwan_request *request,
   444	                                     const char *space)
   445	{
   446	    struct lwan_request_parser_helper *helper = request->helper;
   447	
   448	    /* Most of the time, fragments are small -- so search backwards */
   449	    char *fragment = memrchr(request->url.value, '#', request->url.len);
   450	    if (fragment) {
   451	        *fragment = '\0';
   452	        helper->fragment.value = fragment + 1;
   453	        helper->fragment.len = (size_t)(space - fragment - 1);
   454	        request->url.len -= helper->fragment.len + 1;
   455	    }
   456	
   457	    /* Most of the time, query string values are larger than the URL, so
   458	       search from the beginning */
   459	    char *query_string = memchr(request->url.value, '?', request->url.len);
   460	    if (query_string) {
   461	        *query_string = '\0';
   462	        helper->query_string.value = query_string + 1;
   463	        helper->query_string.len =
   464	            (size_t)((fragment ? fragment : space) - query_string - 1);
   465	        request->url.len -= helper->query_string.len + 1;
   466	    }
   467	}
