   142	strsep_char(char *strp, char delim)
   143	{
   144	    char *ptr;
   145	
   146	    if (UNLIKELY(!strp))
   147	        return NULL;
   148	
   149	    ptr = strchr(strp, delim);
   150	    if (UNLIKELY(!ptr))
   151	        return NULL;
   152	
   153	    *ptr = '\0';
   154	    return ptr + 1;
